      };

      function Button({ className = "", id = "", text, type = "button", dataAction = "" }) {
        const idAttribute = id ? ` id="${id}"` : "";
        const actionAttribute = dataAction ? ` data-action="${dataAction}"` : "";

        return `<button type="${type}"${idAttribute} class="${className}"${actionAttribute}>${text}</button>`;
      }

      function ImagePreview({ title, collection, description, fileName, src }) {
        return `
          <main class="page-shell" id="main-content">
            <section class="hero" aria-labelledby="page-title">
              <article class="image-card">
                <div class="preview-frame">
                  <img src="${src}" alt="${description}">
