                  <div>
                    <p class="eyebrow">${collection}</p>
                    <h1 id="page-title">${title}</h1>
                    <p class="summary">
                      Previewing <strong>${fileName}</strong>. Delete it only if you no longer want this image in your library.
                    </p>
                  </div>
                  <div class="actions" aria-label="Image actions">
                    <button type="button" id="delete-trigger" class="trigger">Delete image</button>
                    ${Button({ className: "secondary-button", text: "Keep image" })}
                  </div>
                  <p class="status" id="delete-status" role="status" aria-live="polite"></p>
                </div>
              </article>
            </section>
