  await page.click('.trigger');
  const isOpen = await page.$eval('#delete-dialog', (dialog) => dialog.open);
  const activeId = await page.evaluate(() => document.activeElement && document.activeElement.id);
  const opened = await runAxe('opened');
  await browser.close();

  const payload = { isOpen, activeId, results: [closed, opened] };
  console.log(JSON.stringify(payload, null, 2));
  const wcag = payload.results.flatMap((r) => r.violations.filter((v) => !v.tags.includes('best-practice')).map((v) => ({ ...v, state: r.label })));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
